-- Objective brief state: human-facing descriptions, independent title and
-- description ownership, current-instruction authorship, durable generation
-- intent and removal suppression (coo:1275, contract ADR 0057). Same semantics
-- as the SQLite migration of the same name.
--
-- Every column is additive and nullable or defaulted, so existing rows keep
-- their meaning:
--
-- * `title_source` stays NULL on existing rows. NULL means "provenance not
--   known"; services treat it as owned and never replace it automatically.
-- * Descriptions start empty. No summary is generated by this migration.
-- * `instruction_author_kind` is backfilled only where creation provenance
--   still describes the current instruction text: a live row with non-blank
--   instructions whose change feed records no instruction edit. Every other
--   row stays NULL (unknown authorship), which never qualifies for an
--   automatic summary.
-- * `revision` and `updated_at` are not moved: no observable field changes.

ALTER TABLE objectives ADD COLUMN IF NOT EXISTS title_source text
  CHECK (title_source IS NULL OR title_source IN ('generated', 'agent', 'user'));
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS title_generation integer NOT NULL DEFAULT 0
  CHECK (title_generation >= 0);
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS title_status text
  CHECK (title_status IS NULL OR title_status IN ('pending', 'failed'));

ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_source text
  CHECK (description_source IS NULL OR description_source IN ('generated', 'agent', 'user'));
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_instruction_hash text;
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_author_workspace_user_id text;
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_author_agent text;
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_updated_at timestamptz;
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_revision integer NOT NULL DEFAULT 0
  CHECK (description_revision >= 0);
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_suppressed boolean NOT NULL DEFAULT false;
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_generation integer NOT NULL DEFAULT 0
  CHECK (description_generation >= 0);
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_status text
  CHECK (description_status IS NULL OR description_status IN ('pending', 'failed'));
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_request_kind text
  CHECK (description_request_kind IS NULL OR description_request_kind IN ('automatic', 'explicit'));
ALTER TABLE objectives ADD COLUMN IF NOT EXISTS description_failure_code text;

ALTER TABLE objectives ADD COLUMN IF NOT EXISTS instruction_author_kind text
  CHECK (instruction_author_kind IS NULL OR instruction_author_kind IN ('human', 'agent', 'automation'));

UPDATE objectives o
   SET instruction_author_kind = o.created_by_kind
 WHERE o.deleted_at IS NULL
   AND o.instruction_author_kind IS NULL
   AND btrim(COALESCE(o.instruction_text, '')) <> ''
   AND NOT EXISTS (
     SELECT 1
       FROM entity_changes ec
      WHERE ec.entity_type = 'objective'
        AND ec.entity_id = o.id
        AND ec.operation = 'update'
        AND ec.changed_fields_json @> '["instruction_text"]'::jsonb
   );
